import sys

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m, k = map(int, lines[0].split())

    blocked = set()
    for i in range(1, k + 1):
        xi, yi = map(int, lines[i].split())
        blocked.add((xi, yi))

    parts = lines[k + 1].split()
    xs, ys = int(parts[0]), int(parts[1])
    direction = parts[2]

    dx = {'NE': -1, 'NW': -1, 'SE': 1, 'SW': 1}
    dy = {'NE': 1, 'NW': -1, 'SE': 1, 'SW': -1}

    # When reflection happens, we need to reverse the appropriate direction component
    # NE <-> SW, NW <-> SE
    dir_reverse = {'NE': 'SW', 'SW': 'NE', 'NW': 'SE', 'SE': 'NW'}

    cx, cy = xs, ys
    cd = direction

    visited = set()
    cells = set()

    while True:
        state = (cx, cy, cd)
        if state in visited:
            break
        visited.add(state)
        cells.add((cx, cy))

        nx, ny = cx + dx[cd], cy + dy[cd]

        hit_blocked = False
        hit_border = False

        if (nx, ny) in blocked:
            hit_blocked = True
        elif nx < 1 or nx > n or ny < 1 or ny > m:
            hit_border = True

        if hit_blocked or hit_border:
            # Determine which border was hit and reflect appropriately
            if nx < 1 or nx > n:
                # Hit vertical border - reverse x component
                if cd == 'NE' or cd == 'NW':
                    cd = dir_reverse['NE'] if cd == 'NE' else dir_reverse['NW']
                    # Reverse NE <-> SW, NW <-> SE
                elif cd == 'SE' or cd == 'SW':
                    cd = dir_reverse['SE'] if cd == 'SE' else dir_reverse['SW']
            if ny < 1 or ny > m:
                # Hit horizontal border - reverse y component
                if cd == 'NE' or cd == 'SE':
                    cd = dir_reverse['NE'] if cd == 'NE' else dir_reverse['SE']
                elif cd == 'NW' or cd == 'SW':
                    cd = dir_reverse['NW'] if cd == 'NW' else dir_reverse['SW']

            # Calculate where we are after reflection (back inside the grid)
            if nx < 1: nx = 1
            elif nx > n: nx = n
            if ny < 1: ny = 1
            elif ny > m: ny = m

        cx, cy = nx, ny

    return str(len(cells)) + '\n'
