def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    arr = list(map(int, lines[1].split()))

    empty_pos = []
    used_val = set()

    for i in range(n):
        if arr[i] != -1:
            used_val.add(arr[i])
        else:
            empty_pos.append(i + 1)  # 1-indexed positions

    m = len(empty_pos)
    available_val = set(range(1, n + 1)) - used_val

    s_size = 0
    for pos in empty_pos:
        if pos in available_val:
            s_size += 1

    MOD = 1000000007

    # Precompute factorials
    fact = [1] * (m + 1)
    for i in range(1, m + 1):
        fact[i] = (fact[i-1] * i) % MOD

    # Precompute inverse factorials using Fermat's little theorem
    inv_fact = [1] * (m + 1)
    inv_fact[m] = pow(fact[m], MOD - 2, MOD)
    for i in range(m - 1, -1, -1):
        inv_fact[i] = (inv_fact[i + 1] * (i + 1)) % MOD

    ans = 0
    for k in range(s_size + 1):
        # C(s_size, k) = s_size! / (k! * (s_size-k)!)
        comb = fact[s_size] * inv_fact[k] % MOD * inv_fact[s_size - k] % MOD
        # term = C(s_size, k) * (m - k)!
        term = comb * fact[m - k] % MOD
        if k % 2 == 1:
            ans = (ans - term + MOD) % MOD
        else:
            ans = (ans + term) % MOD

    return str(ans)
