        k = len(seq)
        if k <= 2:
            return True
        if all(x == 0 for x in seq):
            return True
        if seq[0] == 0:
            return False

        # For non-zero sequences, use cross multiplication to avoid floating point issues
        # Check: seq[i] / seq[i-1] = ratio for all i
        # Equivalent to: seq[i] * seq[0] = seq[i-1] * seq[1]
        for i in range(1, k):
            if seq[i] * seq[0] != seq[i-1] * seq[1]:
                return False
        return True

    # Check if sequence is already a GP
    if is_gp(a):
        return '0\n'

    # Try removing each element and check
    for i in range(n):
        new_seq = a[:i] + a[i+1:]
        if is_gp(new_seq):
            return '1\n'

    return '2\n'
