def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "NO"

    parts = lines[0].split()
    if len(parts) < 2:
        return "NO"

    n, m = int(parts[0]), int(parts[1])

    # For very small cases or edge handling
    if n == 0:
        return "YES\n"

    adj = [[] for _ in range(n)]
    edges = []

    # Build adjacency list and store edges
    for i in range(1, len(lines)):
        if i >= m + 1:
            break
        parts = lines[i].split()
        if len(parts) < 3:
            continue
        a, b, c = int(parts[0]), int(parts[1]), int(parts[2])
        a -= 1  # 0-indexed
        b -= 1
        adj[a].append((b, c))
        adj[b].append((a, c))
        edges.append((a, b, c))

    # Track assignments: node -> value
    assigned = {}

    def solve(start_node):
        """DFS traversal that assigns values and checks local consistency"""
        assigned[start_node] = 0.0
        current_val = assigned[start_node]
        assigned[start_node] = current_val

        stack = [start_node]
        while stack:
            u = stack.pop()
            u_val = assigned[u]

            for v, c in adj[u]:
                # Constraint: x[u] + x[v] = c
                expected_v = c - u_val

                if v in assigned:
                    # Already visited - check consistency
                    if abs(assigned[v] - expected_v) > 1e-6:
                        return None
                else:
                    assigned[v] = expected_v
                    stack.append(v)

        return True

    # Process each node
    for i in range(n):
        if i not in assigned:
            assign = solve(i)
            if assign is None:
                return "NO"

    # Verify all edges satisfy their constraints
    for u, v, c in edges:
        if u in assigned and v in assigned:
            edge_sum = assigned[u] + assigned[v]
            # Allow small tolerance
            if abs(edge_sum - c) > 1e-6:
                return "NO"

    # All constraints satisfied
    result = []
    for i in range(n):
        if i in assigned:
            # Round to reasonable precision
            val = round(assigned[i], 10)
            # Further round to handle floating point issues
            result.append(str(val))
        else:
            # Should not happen if all nodes visited
            result.append("0.0")

    return "YES\n" + " ".join(result)
