        parts = lines[i + 1].split()
        if len(parts) < 3:
            continue
        u, v, w = int(parts[0]), int(parts[1]), int(parts[2])
        edges.append((u, v, w, i + 1))

    def process(n, edges, lamda):
        mod = [(w + lamda if u == 1 or v == 1 else w, i + 1, u, v) for i, (u, v, w, _) in enumerate(edges)]
        mod.sort(key=lambda x: (x[0], x[1]))

        parent = list(range(n + 1))
