            if ru != rv:
                parent[ru] = rv
                sel.append(idx)
                if u == 1 or v == 1:
                    cap_cnt += 1

        parent = list(range(n + 1))
        for u, v, w, _ in edges:
            ru, rv = find(parent, u), find(parent, v)
            if ru != rv:
                parent[ru] = rv

        roots = {find(parent, x) for x in range(1, n + 1)}
        return (len(roots) == 1, cap_cnt, sel)

    # Exponential/ampling search through log scale
    checked = []
    for exp in range(-10, 11):
