                s2 = s2.ljust(m, 'A')[:m]

                ac = count_ac_in_sk(s1, s2, k)
                if ac == x:
                    return f"{s1}\n{s2}\n"
                if s1.count("AC") + s2.count("AC") <= x <= ac:
                    pass

